// The glossary: every term of art used in the tutorial.
//
//   window.RIGDATA.GLOSSARY = [{ term, variants, definition, quote, source, later, spellings, see }]
//
//   term        the form the tutorial uses
//   variants    other spellings and names, period or later
//   definition  plain words
//   quote       a period definition, where the research notes have one
//   source      where the quotation or the usage comes from
//   later       true when the term (not the thing) is later than 1790–1815
//   spellings   which source uses which spelling, where that is known
//   see         related terms
//
// Any page may load this file for the data alone. On glossary.html (a page with
// an element of id "glossary") it also draws the list. Each entry's id is its
// term in lower case with spaces turned to hyphens and apostrophes dropped, so
// other pages can link to glossary.html#clewline. A link to a variant
// (glossary.html#clue-line) is resolved to its entry as well.
//
// S = Steel 1794, L = Lever 1808/1819, F = Falconer 1769 in the notes below.

(function () {
  const R = (window.RIGDATA = window.RIGDATA || {});

  const STEEL = 'Steel 1794', LEVER = 'Lever 1808', FALC = 'Falconer 1769';

  R.GLOSSARY = [
    // ---- Tackles and blocks --------------------------------------------------
    { term: 'tackle', variants: ['purchase'], definition: 'A rope rove through blocks so that a light pull over a long distance moves a heavy weight a short one.', quote: 'a machine formed by the connection of a rope or fall, with an assemblage of blocks', source: `${STEEL}, p.176`, see: ['fall', 'purchase'] },
    { term: 'purchase', variants: [], definition: 'Any arrangement of blocks and rope that multiplies a pull, and the advantage it gives. Steel: its power is “as the number of parts of the fall that are applied to sustain the weight”.', source: `${STEEL}, pp.176–177`, see: ['tackle'] },
    { term: 'fall', variants: [], definition: 'The rope of a tackle. Also, loosely, just the loose end that is hauled on.', quote: 'The rope that connects the blocks of a tackle; but the fall sometimes implies only the loose part which is pulled upon.', source: `${STEEL}, p.166`, see: ['standing part', 'leading part'] },
    { term: 'standing part', variants: ['standing-part'], definition: 'The fixed end of a rope: in a tackle, the end made fast to one of the blocks.', quote: 'That part of the fall which is fastened to one of the blocks, is called the standing-part, and the other parts of it are called the running-part.', source: `${STEEL}, p.176`, see: ['leading part'] },
    { term: 'running part', variants: ['running-part'], definition: 'Every part of a tackle’s fall other than the standing part: the parts that run through the blocks.', source: `${STEEL}, p.176` },
    { term: 'leading part', variants: ['leading-part', 'hauling part'], definition: 'The end of a rope that is hauled on.', quote: 'That part of a tackle which is hauled upon.', source: `${STEEL}, p.168`, spellings: 'Steel: leading-part, and “hauling part of the fall” in his worked example. Lever: “the Fall, or part hauled upon”.' },
    { term: 'pendent', variants: ['pendant'], definition: 'A short heavy rope with a block or tackle at one end. It takes the load where the load is, and the tackle is put on its other end.', quote: 'serve to transmit the effort of their tackles to some other object', source: `${STEEL}, p.171`, spellings: 'Steel’s text: pendent. Steel’s tables: pendants. Modern: pendant.' },
    { term: 'runner', variants: [], definition: 'A single thick rope with a tackle on its end. Rove through a block on the load as a whip, it doubles what the tackle gives.', quote: 'a single rope, connected with a tackle, which transmits its effort the same as if the tackle was the whole length', source: `${STEEL}, p.173`, see: ['runner and tackle'] },
    { term: 'tye', variants: ['tie'], definition: 'The thick rope by which a topsail or topgallant yard is hoisted. The halliards are the tackle on its lower end.', quote: 'a sort of runner, or large rope, used to convey the effort of the tackle to hoist the upper yards and gaff', source: `${STEEL}, p.179`, spellings: 'Steel, Lever and Falconer: tye. Modern: tie.', see: ['halliard', 'fly-block'] },
    { term: 'span', variants: [], definition: 'A short rope with a block or thimble at each end, hitched round a mast, cap or stay to lead ropes through.', quote: 'to lead ropes through', source: `${STEEL}, p.174` },
    { term: 'whip', variants: ['single whip'], definition: 'The simplest purchase: a rope rove through one single block. With the block fixed it only turns the lead; with the block on the load it doubles the pull.', quote: 'a small single tackle, formed by connecting the fall to a single block, or with two blocks, the one fixed, and the other moveable', source: `${STEEL}, p.179; ${LEVER}; ${FALC}, WHIP` },
    { term: 'whip upon whip', variants: [], definition: 'One whip with the block of a second whip made fast to its fall. Four to one with two single blocks.', quote: 'two single block[s] will afford the same purchase as a tackle, having a double and a single block, and with much less friction', source: `${STEEL}, p.180` },
    { term: 'gun-tackle purchase', variants: ['gun tackle'], definition: 'Two single blocks, the standing part made fast to the strap of one of them. Two or three to one, depending on which block moves.', source: `${LEVER}, “Blocks, Tackles”; ${STEEL}, p.232` },
    { term: 'luff tackle', variants: [], definition: 'A double and a single block, each with a hook. The general-purpose tackle. Three or four to one.', quote: 'a double and single Block: each strapped with a Hook and Thimble', source: `${LEVER}, “Blocks, Tackles”; ${STEEL}, pp.176–177` },
    { term: 'jigger', variants: ['tail tackle', 'jigger tackle'], definition: 'A luff tackle whose blocks have tails of rope in place of hooks, so that it can be clapped on to any rope. Used for topping the lower yards by their lifts.', quote: 'used for topping the main and fore yards by the lifts', source: `${STEEL}, p.177; ${LEVER}, “Blocks, Tackles”` },
    { term: 'luff upon luff', variants: [], definition: 'One luff tackle clapped on the fall of another. Used to set up stays and bobstays.', source: `${STEEL}, pp.195, 200` },
    { term: 'burton', variants: ['top-burton', 'top burton tackle'], definition: 'A small tackle of a double and a single block, hooked to the burton pendents at a topmast head. It sets up the topmast shrouds and supports the topsail yard.', quote: 'composed of double and single blocks, and are used with pendents, to set up the shrouds, support the topsail-yards, &c.', source: `${STEEL}, p.177; ${FALC}, BURTON` },
    { term: 'runner and tackle', variants: [], definition: 'A luff tackle applied to a runner. Used to set up the lanyards of the lower shrouds and the backstays.', quote: 'the same Purchase as a Luff Tackle, applied to a Runner', source: `${LEVER}, “Blocks, Tackles”` },
    { term: 'long tackle', variants: ['long-tackle block', 'fiddle block'], definition: 'A tackle of a long-tackle block and a single block. The long-tackle block has two sheaves one above the other in a long shell; “fiddle block” is the modern name for it. Used for the main bowline tackle and the yard tackles.', source: `${STEEL}, pp.177–178` },
    { term: 'jeers', variants: ['jears', 'jeer tackle'], definition: 'The heavy tackles that hoist a lower yard: in large ships a treble block at the mast-head and a double block on the yard, on each side. Once the yard is up it hangs in its slings and the jeers are eased. “Jeer tackle” is not a general kind of tackle in the period sources.', quote: 'JEARS, in large ships, are two large tackle.', source: `${STEEL}, p.203; ${LEVER}, p.34`, spellings: 'Steel, Lever and Falconer: jears. Modern: jeers.', see: ['slings'] },
    { term: 'winding tackle', variants: [], definition: 'The heaviest purchase in the ship: a fourfold and a treble block, or a treble and a double.', source: `${STEEL}, p.178` },
    { term: 'handy billy', variants: [], later: true, definition: 'A later name for a small jigger or luff tackle kept for odd jobs. Steel and Lever do not use it, and the tutorial leaves it out.', source: 'Absent from Steel 1794 and Lever 1808' },
    { term: 'Spanish burton', variants: [], later: true, definition: 'A purchase named in later seamanship books. Steel and Lever do not use the name.', source: 'Absent from Steel 1794 and Lever 1808' },
    { term: 'watch tackle', variants: [], later: true, definition: 'A later name for a small luff tackle. Steel and Lever do not use it.', source: 'Absent from Steel 1794 and Lever 1808' },
    { term: 'block', variants: [], definition: 'A wooden shell holding one or more sheaves on a pin, through which a rope is rove. Single, double, treble and fourfold by the number of sheaves.', source: `${STEEL}, block-making` },
    { term: 'sheave', variants: ['sheeve'], definition: 'The grooved wheel in a block. Also a wheel let into a spar, a bitt or the ship’s side, in a sheave-hole.', source: `${STEEL}, passim` },
    { term: 'strap', variants: ['strop'], definition: 'The band of rope round a block by which it is made fast. Blocks in this period are rope-strapped; iron straps are later.', source: `${STEEL} and ${LEVER}, passim`, spellings: 'Steel and Lever: strap. Later: strop.' },
    { term: 'becket', variants: [], definition: 'A small loop of rope: on a block, the eye to which the standing part of the fall is made fast; elsewhere, a loop to hook or hang something to.', source: `${STEEL}, p.204 (topsail lift hooked to “a becket round the topmast-cap”)` },
    { term: 'thimble', variants: [], definition: 'A ring with a grooved rim, seized into an eye in a rope so that another rope or a hook can pass through it without chafe.', source: `${STEEL}, passim` },
    { term: 'snatch block', variants: ['snatch-block'], definition: 'A block open at one side, so that the bight of a rope can be dropped into it without reeving the end. The main brace leads through one on the gunwale right aft.', source: `${STEEL}, pp.202, 214` },
    { term: 'shoe-block', variants: ['shoe block'], definition: 'A block with an upper and a lower sheave. On a course’s buntlines the two legs are one rope through its upper sheave and the fall goes through its lower sheave.', source: `${LEVER}, p.52` },
    { term: 'sister block', variants: ['sister-block'], definition: 'A block with two sheaves one above the other, seized between the two foremost topmast shrouds. The upper sheave takes the reef-tackle pendent and the lower the topsail lift.', source: `${STEEL}, pp.204–205; ${LEVER}, p.38` },
    { term: 'quarter block', variants: ['quarter-block'], definition: 'The block under a lower yard near the slings through which the topsail sheet turns down to the deck.', quote: 'A quarter-block is a double-block, with a thick and thin sheave running on the same pin; and, though used for the topsail sheets, and intended for the clue-lines, a single block would be cheaper and better, as the thin sheave is seldom used for the clue-line', source: `${STEEL}, p.203` },
    { term: 'shoulder block', variants: ['shouldered block', 'shouldered-block'], definition: 'The block at a lower yard-arm through which the topsail sheet first reeves. The lift block is spliced into its strap.', source: `${STEEL}, pp.203, 212; ${LEVER}, p.54` },
    { term: 'fly-block', variants: ['fly block', 'tye-block'], definition: 'The block spliced into the lower end of a topsail tye, the upper block of the halliards. Lever’s word. The tye-block proper is the block on the yard through which the tye reeves.', source: `${LEVER}, p.38; ${STEEL}, p.205` },
    { term: 'jack-block', variants: ['jack block'], definition: 'A block buttoned round the topgallant mast when a topgallant yard is to be sent up or down, for the yard-rope.', source: `${STEEL}, pp.213–214; ${LEVER}, pp.47–48, 86` },
    { term: 'jewel block', variants: ['jewel-block'], definition: 'A small block at the very end of a topsail or topgallant yard for the studding-sail halliards.', quote: 'Small blocks, seized to eye-bolts in the extremities of the upper yards, for hoisting the studding-sails by the haliards', source: `${STEEL}, rigging terms` },
    { term: 'leading block', variants: ['lead block'], definition: 'A fixed block that only changes the direction of a rope, to bring it to where it can be hauled. It adds no power.', quote: 'are only for the convenience of turning the direction of the fall, they add nothing to the power of the purchase, but, on the contrary, destroy so much as is necessary to overcome their friction', source: `${STEEL}, p.177 (of fixed blocks)` },
    { term: 'tail block', variants: ['tail-block'], definition: 'A block whose strap ends in a tail of rope, to be hitched round a spar or rope for the occasion.', source: `${STEEL}, p.210` },
    { term: 'monkey-block', variants: ['monkey block'], definition: 'A small block fixed on a yard. In the merchant service the topsail buntlines lead through monkey-blocks on the yard, which makes them act as downhaul tackles.', source: `${LEVER}, p.55` },
    { term: 'nine-pin block', variants: [], definition: 'A block set upright in the breast-work for running rigging that leads down by the mast to reeve through.', quote: 'is placed in the breast-work, for the running rigging, which leads down by the mast, to reeve through', source: `${LEVER}` },
    { term: 'cheek block', variants: ['cheek-block'], definition: 'A block fixed against the side of a mast-head. Those at the fore topmast head take the jib stay and the jib and staysail halliards.', source: `${STEEL}, pp.209–210` },
    { term: 'bees', variants: ['bee'], definition: 'The planks bolted to the outer end of the bowsprit, with holes and sheaves through which the fore topmast stays lead.', source: `${STEEL}, p.2` },
    { term: 'heart', variants: [], definition: 'A heart-shaped block of wood with one large hole, used in pairs with a lanyard to set up a stay.', source: `${STEEL}, pp.200–201` },
    { term: 'deadeye', variants: ['dead-eye', 'dead eye'], definition: 'A round wooden block with three holes and no sheaves. A shroud ends in one, and a lanyard rove between it and a second on the channel sets the shroud up. Light ropes are also hitched to the shrouds at the deadeyes.', quote: 'Round flat wooden blocks, with three holes instead of sheaves', source: `${STEEL}, rigging terms` },
    { term: 'lanyard', variants: ['laniard'], definition: 'The rope rove between two deadeyes or hearts to set up a shroud or stay; any short rope used to lash or set something up.', source: `${STEEL}, p.198`, spellings: 'Steel’s text and Lever: laniard. Steel’s tables: lanyard.' },
    { term: 'truck', variants: ['shroud truck', 'shroud-truck', 'seizing-truck'], definition: 'A small wooden fairlead with a hole through it. Shroud trucks are seized to the shrouds to lead ropes down so “that they may be more readily found”; over a hundred came from the wreck of Invincible (1758). The trucks of a parrel are its rollers.', source: `${STEEL}, p.179; Cousins 2022, p.68` },
    { term: 'selvagee', variants: [], definition: 'A soft strap made of rope-yarns, used to clap a tackle on to a rope or spar. The definition is general knowledge; the notes use the word without defining it.', source: `${STEEL}, pp.233, 235 (usage)` },
    { term: 'lizard', variants: [], definition: 'A thimble spliced on a short tail of rope. The one on each main bowline is where the bowline tackle hooks.', quote: 'Four feet from the bridle is a thimble, spliced and pointed on each bowline, called a lizard, to which is hooked a bowline-tackle', source: `${STEEL}, pp.211–212` },
    { term: 'cringle', variants: [], definition: 'A loop of rope worked into the bolt-rope at the edge of a sail, to which a rope is made fast: earing cringles, reef cringles, bowline cringles, buntline cringles.', source: `${STEEL}, pp.210–212` },
    { term: 'toggle', variants: [], definition: 'A wooden pin through an eye, so that a rope can be cast off quickly. The topgallant bowlines are toggled so they can be let go when the yard is sent down.', source: `${STEEL}, p.213` },
    { term: 'mouse', variants: [], definition: 'A pear-shaped swelling raised on a stay with spun-yarn. The stay’s end passes through its own eye and the mouse stops it, forming the collar round the mast-head.', source: `${STEEL}, p.187` },
    { term: 'collar', variants: [], definition: 'The eye of a stay round the mast-head; also a strap lashed round a mast or the bowsprit with a heart or thimble in it, to which a stay sets up.', source: `${STEEL}, pp.200–201` },
    { term: 'clinch', variants: ['clench'], definition: 'To make a rope’s end fast to a ring, cringle or spar with a seized loop. Standing parts are “clinched” in Steel’s leads.', source: `${STEEL}, passim` },
    { term: 'seizing', variants: ['seize'], definition: 'A lashing of small line binding two ropes, or a rope and a spar, together.', source: `${STEEL}, passim` },
    { term: 'fid', variants: [], definition: 'The bar through the heel of a topmast or topgallant mast that rests on the trestle-trees and holds the mast up. To strike the mast the fid is taken out.', source: `${LEVER}, p.86` },
    { term: 'traveller', variants: [], definition: 'An iron ring that slides along a spar or rope. The jib’s tack hooks to one on the jib-boom; a topgallant yard coming down is kept to windward by one on the backstay.', quote: 'a circular iron hoop, with a hook and shackle, used to haul out the tack of the jib', source: `${STEEL}, rigging terms` },
    { term: 'hanks', variants: [], definition: 'The rings by which a staysail or jib slides on its stay.', source: `${STEEL}, pp.209–210` },
    { term: 'goose-neck', variants: ['gooseneck'], definition: 'An iron hook at the heel of a boom, hooked to an eye so that the boom can swing: on the driver boom and the lower studding-sail boom.', quote: 'a large iron Hook, called a Goose Neck, driven into the inner End', source: `${LEVER}, p.64` },
    { term: 'boom iron', variants: ['boom-iron'], definition: 'The iron fitting on a yard through which a studding-sail boom slides out.', quote: 'Two flat iron rings formed into one piece, one above the other… the lower ring is the largest, and is driven on the yard', source: `${STEEL}, rigging terms; p.35` },

    // ---- Spars -------------------------------------------------------------
    { term: 'yard', variants: [], definition: 'A spar hung across a mast to spread the head of a square sail. From the middle outwards its parts are the slings, the quarters and the yard-arms.', source: `${STEEL}, pp.202–207` },
    { term: 'yard-arm', variants: ['yardarm', 'yard arm'], definition: 'The outer end of a yard, outside the stop cleats.', source: `${STEEL}, p.202` },
    { term: 'slings', variants: ['chain slings', 'top-chains', 'preventer slings'], definition: 'Two things. The middle of a yard. And the ropes (in action, chains) by which a lower yard hangs from the mast-head once it has been hoisted.', quote: 'The Jears or Tackles, are then eased off, and the Yard hangs by the Slings', source: `${LEVER}, p.35; ${STEEL}, p.204`, see: ['jeers'] },
    { term: 'quarters', variants: ['quarter'], definition: 'Of a yard: the parts between the slings and the yard-arms. Of the ship: her sides near the stern.', source: `${STEEL}, pp.202–203` },
    { term: 'truss', variants: ['truss pendents', 'truss-pendents'], definition: 'The ropes that hold a lower yard in to its mast. They pass round yard and mast, and a tackle on each slackens or tightens them.', quote: 'by which the truss-pendent is slackened or straightened, to let the yard move from, or confine it strictly to, the mast', source: `${STEEL}, p.204; ${LEVER}, pp.36–37` },
    { term: 'nave-line', variants: ['nave line'], definition: 'A light line from under the top that holds the truss pendents up level with the yard.', source: `${STEEL}, p.204; ${LEVER}, p.37` },
    { term: 'puddening', variants: ['pudding'], definition: 'A thick wreath of rope round a lower mast under the yard, to hold the yard if its gear is shot away.', quote: 'A thick wreath, made of rope, fastened about the main and fore masts of a ship, to prevent their yards from falling down, when the ropes that support them are injured', source: `${STEEL}, rigging terms; p.233`, see: ['dolphin'] },
    { term: 'dolphin', variants: [], definition: 'A plaited wreath of rope round a lower mast that supports the puddening.', quote: 'to sustain the weight of the fore and main-yards, in case the rigging, or chains, by which those yards are suspended, should be shot away in the time of battle', source: `${FALC}, DOLPHIN` },
    { term: 'lift', variants: ['lifts'], definition: 'A rope from the mast-head or cap to a yard-arm. The lifts square the yard, top one end above the other, and take the weight of the men on it.', quote: 'Ropes which suspend the outer-quarters of the yards, and raise or lower them', source: `${STEEL}, p.169; ${FALC}, LIFTS` },
    { term: 'topping', variants: ['top', 'top up'], definition: 'Raising one yard-arm above the other with the lifts; raising the end of a boom with its topping lift.', quote: 'The act of drawing one of the yard-arms higher than the other, by slackening one lift, and pulling upon the other', source: `${STEEL}, p.179` },
    { term: 'halliard', variants: ['haliard', 'hallyard', 'halyard', 'halliards'], definition: 'The rope or tackle that hoists a yard or a sail. On a topsail or topgallant yard the halliards are the tackle on the lower end of the tye.', source: `${STEEL}, pp.205–206; ${LEVER}, p.38`, spellings: 'Steel’s text: haliard. Steel’s tables: hallyard. Lever: halliards. Falconer: haliards. Dana and Totten (later, American): halyard.', see: ['tye'] },
    { term: 'parrel', variants: ['parral'], definition: 'The collar that holds a topsail or topgallant yard to its mast and lets it slide up and down: ropes rove through wooden ribs and trucks.', quote: 'THE PARRAL is fastened round the aftside of the mast, and round the yard, to fasten the yard to the mast', source: `${STEEL}, p.205; ${LEVER}, p.39`, spellings: 'Steel and Lever: parral. Falconer: parrel.' },
    { term: 'brace', variants: ['braces'], definition: 'The rope from a yard-arm by which the yard is swung round the mast. Most are a whip, through a block at the yard-arm.', quote: 'A rope to turn the yards and sails horizontally about the masts', source: `${STEEL}, p.163; ${FALC}, BRACE` },
    { term: 'brace pendent', variants: ['brace pendant'], definition: 'A short rope over the yard-arm with the brace block in its end. Lever: “Brace Pendents are now seldom used”; Lees is reported to date their end to 1815.', source: `${STEEL}, p.202; ${LEVER}, p.33` },
    { term: 'preventer brace', variants: ['preventer braces'], definition: 'A second brace rigged in war and led the opposite way from the working brace, so that one shot does not cut both.', quote: 'A rope used in ships of war, to supply the place of a brace, should that be shot away or damaged. They are led the contrary way, to be less liable to detriment at the same time', source: `${STEEL}, p.163` },
    { term: 'preventer', variants: [], definition: 'Any additional rope rigged to back up another: preventer braces, preventer stays, preventer slings, preventer backstays.', quote: 'a temporary brace, fixed occasionally to succour the main or fore-yard', source: `${FALC}, PREVENTER (the older, heavy-weather sense)` },
    { term: 'yard tackle', variants: ['yard-tackle'], definition: 'A tackle on a pendent at each arm of the fore and main yards, for hoisting in boats and stores. Triced up along the yard when idle.', quote: 'to hoist in the boats, &c.', source: `${STEEL}, p.202` },
    { term: 'tricing line', variants: ['tricing-line'], definition: 'A light line that hauls something up out of the way: the yard tackles along the yard, the heel of a studding-sail boom, a travelling backstay.', source: `${STEEL}, p.202` },
    { term: 'horses', variants: ['horse'], definition: 'The ropes under a yard, jib-boom or boom on which the men stand. The period word in Steel, Lever and Falconer; “footropes” is later. A horse is also a rope or bar along which a sheet block travels.', quote: 'HORSES go over the yard-arms with an eye in their outer ends, and stop against the cleats, and hang about three feet below the yard', source: `${STEEL}, p.202; ${LEVER}, p.33`, see: ['footrope', 'stirrups', 'Flemish horse'] },
    { term: 'footrope', variants: ['foot rope', 'foot-rope'], later: true, definition: 'The later name for the horses under a yard. None of Steel, Lever (1819) or Falconer uses it in that sense. In Lever “foot rope” means the bolt-rope along the foot of a sail.', source: `${LEVER}, p.50 (the other sense)`, see: ['horses'] },
    { term: 'stirrups', variants: ['stirrup'], definition: 'Short ropes hanging from a yard with a thimble or eye in the lower end through which the horse passes, to hold it up.', source: `${STEEL}, p.202` },
    { term: 'Flemish horse', variants: ['flemish-horse'], definition: 'A short extra horse at each arm of a topsail yard, for the man at the earing. Lower yards have none.', source: `${STEEL}, p.204; ${LEVER}, p.38` },
    { term: 'yard-rope', variants: ['yard rope', 'top-rope', 'top rope'], definition: 'The rope by which a topgallant yard is sent up or down, rove through the jack-block. Also a temporary rope used to get a sail up to its yard for bending.', source: `${STEEL}, pp.210, 213–214; ${LEVER}, pp.47–48, 86` },
    { term: 'rolling tackle', variants: ['rolling-tackle'], definition: 'A luff tackle from the quarter of a topsail yard to the mast, bowsed taut to stop the yard working against the mast as the ship rolls.', quote: 'which confines the Yard so that it has no play to chafe the Mast', source: `${LEVER}, p.86; ${STEEL}, pp.177, 233` },
    { term: 'set flying', variants: ['flying'], definition: 'Of a sail: set from the deck without permanent gear. The royals are set flying, with halliards only and the clews lashed to the topgallant yard-arms.', quote: 'FLYING OF SAILS. Setting them in [a] loose manner; as royal sails without lifts, or sheets, the clues being lashed', source: `${STEEL}, p.166` },
    { term: 'crossjack', variants: ['cross-jack', 'crojeck', 'cross-jack-yard'], definition: 'The lower yard on the mizen mast. It carries no sail in this period; it is there to spread the foot of the mizen topsail.', quote: 'The CROSS-JACK-YARD is used to expand the foot of the mizen topsail', source: `${STEEL}, p.180; ${FALC}, CROSS-JACK`, spellings: 'Steel and Falconer: cross-jack, “pronounced crojeck” (Falconer).' },
    { term: 'mizen yard', variants: ['mizzen yard'], definition: 'The long lateen yard on the mizen mast, with the sail set only abaft the mast. Still the official fit for a 74 in Steel’s tables of 1794; “entirely laid aside” by 1808 (Lever).', source: `${STEEL}, p.207; ${LEVER}, p.42`, see: ['gaff'] },
    { term: 'gaff', variants: [], definition: 'The spar that spreads the head of the mizen or driver, with jaws round the after side of the mast. It replaced the mizen yard in ships of the line between about 1790 and 1805.', quote: 'A short pole projecting from the mizenmast of ships, except those of the line, to expand the head of the mizen and driver sails', source: `${STEEL}, p.2; ${LEVER}, p.43` },
    { term: 'peak', variants: ['peek'], definition: 'The outer, upper end of a gaff or mizen yard, and the upper after corner of the sail set on it.', source: `${STEEL}, pp.204, 217`, spellings: 'Steel: peek. Lever: peak.' },
    { term: 'throat', variants: ['nock'], definition: 'The inner end of a gaff, at the mast, and the upper fore corner of the sail. Steel calls that corner of the sail the nock.', source: `${STEEL}, p.217; ${LEVER}, p.43` },
    { term: 'vang', variants: ['vangs'], definition: 'A rope from the peak of a gaff or mizen yard to each quarter, to steady it sideways.', quote: 'the braces that keep steady the peek', source: `${STEEL}, rigging terms` },
    { term: 'derrick', variants: [], definition: 'The tackle that holds up the peak of a mizen yard.', source: `${STEEL}, pp.207–208` },
    { term: 'boom', variants: ['driver boom', 'spanker boom'], definition: 'A spar that spreads the foot of a sail: the driver or spanker boom on the mizen mast, the jib-boom, the studding-sail booms.', source: `${STEEL}, p.208; ${LEVER}, pp.44–45` },
    { term: 'topping lift', variants: ['topping-lift'], definition: 'The rope that holds up the outer end of a boom. The driver boom has one each side, and the lee one is slacked so it does not cut into the sail.', source: `${STEEL}, p.208; ${LEVER}, p.44` },
    { term: 'crane lines', variants: [], definition: 'Small lines on the driver boom’s topping lifts for overhauling the lee one.', source: `${LEVER}, p.44` },
    { term: 'guy', variants: ['guys'], definition: 'A rope that steadies a spar sideways: the jib-boom guys, spread by the spritsail yard; the guys of the driver boom and of the lower studding-sail boom.', source: `${STEEL}, pp.195, 208, 218; ${LEVER}, pp.31, 64` },
    { term: 'martingale', variants: ['martingal', 'martingale stay', 'martingal-stay'], definition: 'The stay that holds the jib-boom down, led from the boom end through the foot of the dolphin striker. In Steel “martingal” is the bar itself. The word is also used for the rope that holds a lower studding-sail boom down.', quote: 'The Martingal-stay supports the jib-boom, as the bobstays support the bowsprit', source: `${STEEL}, rigging terms; p.233`, spellings: 'Steel 1794: martingal (the bar), martingal-stay. Moore 1801: martingale (the rope). Lever 1808: martingale stay.', see: ['dolphin striker'] },
    { term: 'dolphin striker', variants: ['dolphin-striker', 'martingal'], definition: 'The bar pointing down from the bowsprit cap that gives the martingale stay its angle. Introduced in 1794 according to Lees (read as snippets only).', quote: 'An ash bar, fixed downwards from the fore-side of the bowsprit-cap, and by which the martingal-stay supports the jib-boom', source: `${STEEL}, rigging terms (under MARTINGAL); ${LEVER}, p.60`, spellings: 'Steel 1794: martingal. Lever 1808: dolphin-striker.' },
    { term: 'boomkin', variants: ['bumkin', 'bumpkin'], definition: 'A short spar projecting from each bow, to the end of which the fore tack is hauled down.', source: `${STEEL}, p.210`, spellings: 'Steel’s text: boomkin. Steel’s tables: bumkin.' },
    { term: 'cathead', variants: ['cat-head', 'cat head'], definition: 'The timber projecting from each bow from which the anchor is hung. It carries a cleat for the fore tack.', source: `${STEEL}, p.210` },
    { term: 'chess-tree', variants: ['chestree', 'chest-tree', 'chesstree'], definition: 'A timber on the ship’s side with a sheave in it, through which the main tack is hauled down and brought inboard.', quote: 'abaft the fore-channels, with a sheave in the upper end', source: `${STEEL}, p.164; ${FALC}, CHESTREES` },
    { term: 'bowsprit', variants: [], definition: 'The great spar projecting over the bow. The stays of the foremast and fore topmast end on it.', source: `${STEEL}, pp.194–196` },
    { term: 'jibboom', variants: ['jib-boom', 'jib boom', 'jibb boom'], definition: 'The spar run out through the bowsprit cap, on which the jib is set. In Steel’s table of proportions “flying jib boom” means this spar.', source: `${STEEL}, p.40; ${LEVER}, p.31` },
    { term: 'flying jibboom', variants: ['flying jib-boom'], definition: 'A further spar beyond the jibboom, for the flying jib. Introduced in 1794 according to Lees; not in Steel’s table for a 74; “sometimes” in Moore (1801).', source: 'Lees (snippets); Moore 1801, BOOM' },
    { term: 'cap', variants: [], definition: 'The block of wood at a mast-head through which the next mast above passes. The bowsprit cap does the same for the jibboom.', source: `${STEEL}, pp.1–3` },
    { term: 'top', variants: [], definition: 'The platform at the head of a lower mast. It spreads the topmast shrouds, and a good deal of light gear is worked and belayed there.', source: `${STEEL}, p.37` },
    { term: 'lubber’s hole', variants: ['square of the top', 'lubbers hole'], definition: 'The opening in the top beside the mast-head. Clew-lines, buntlines and bowlines come down through it.', source: `${STEEL}, p.212 (“the square of the top”); ${LEVER}, p.54`, spellings: 'Steel: the square of the top. Lever: Lubber’s Hole.' },
    { term: 'trestle-trees', variants: ['tressle-trees', 'trestle trees'], definition: 'The two fore-and-aft timbers at a mast-head on which the top or the cross-trees rest, and on which the mast above is fidded.', source: `${STEEL}, pp.24–25`, spellings: 'Steel: trestle-trees. Lever: Tressle-trees.' },
    { term: 'cross-trees', variants: ['crosstrees', 'cross trees'], definition: 'The athwartship timbers at a topmast head that spread the topgallant shrouds.', source: `${STEEL}, pp.24–25` },
    { term: 'hounds', variants: [], definition: 'The shoulders near the head of a mast on which the trestle-trees or the rigging rest.', source: `${STEEL}, p.206` },
    { term: 'pole head', variants: ['pole'], definition: 'The part of a topgallant mast above its rigging. With a long pole head the royal is set on it, and no separate royal mast is needed.', source: `${STEEL}, mastmaking` },
    { term: 'royal mast', variants: [], definition: 'A separate mast fidded above the topgallant mast. “Seldom used” in Steel; on a Royal Navy 74 of this period the royal sets on the long pole head of the topgallant mast.', source: `${STEEL}, mastmaking; ${LEVER}, p.58` },
    { term: 'mast-head', variants: ['masthead', 'mast head'], definition: 'The part of a mast above its trestle-trees, to which the mast above is doubled, and round which the shrouds and stays go.', source: `${STEEL}, p.197` },
    { term: 'topmast', variants: ['top-mast'], definition: 'The second mast up, fidded on the trestle-trees of the lower mast and held by its cap. It carries the topsail yard.', source: `${STEEL}, pp.39–40` },
    { term: 'topgallant mast', variants: ['top-gallant mast', 'topgallant-mast'], definition: 'The third mast up, fidded on the topmast trestle-trees. It carries the topgallant yard and, on its pole head, the royal.', source: `${STEEL}, pp.39–40` },
    { term: 'spritsail yard', variants: [], definition: 'The yard slung under the bowsprit. In this period its main job is to spread the jib-boom guys; its sail is going out of use.', source: `${STEEL}, p.196; ${LEVER}, pp.40, 58` },
    { term: 'driver yard', variants: [], definition: 'A small yard that spreads the part of the driver’s head that reaches beyond the peak of the gaff.', source: `${STEEL}, p.40; ${LEVER}, p.66` },

    // ---- Sails ----------------------------------------------------------------
    { term: 'course', variants: ['courses'], definition: 'A sail set on a lower yard: the foresail (fore course) and the mainsail (main course). The mizen was also called the mizen course.', source: `${STEEL}, pp.210–211` },
    { term: 'mainsail', variants: ['main-sail', 'main course'], definition: 'The course on the main yard.', source: `${STEEL}, p.211` },
    { term: 'foresail', variants: ['fore-sail', 'fore course'], definition: 'The course on the fore yard.', source: `${STEEL}, p.210` },
    { term: 'topsail', variants: ['top-sail'], definition: 'The square sail above the course, set on the topmast. The principal working sail, and the one that is reefed.', source: `${STEEL}, pp.204–205, 212` },
    { term: 'topgallant sail', variants: ['top-gallant sail', 'topgallant'], definition: 'The square sail above the topsail. No reefs; its yard is sent down in heavy weather.', source: `${STEEL}, pp.206, 213` },
    { term: 'royal', variants: ['royals'], definition: 'The square sail above the topgallant, a light-airs sail set flying.', quote: 'the highest sail which is extended in any ship', source: `${FALC}, ROYAL; ${STEEL}, p.214` },
    { term: 'staysail', variants: ['stay-sail'], definition: 'A fore-and-aft sail set on a stay. Those before the foremast are triangular; those between the masts are four-sided, except the main staysail.', source: `${STEEL}, pp.106–112, 209–216` },
    { term: 'jib', variants: ['jibb'], definition: 'The headsail set on the jibboom, its tack on a traveller so that it can be hauled out or in.', quote: 'A sail of great command with any side-wind', source: `${FALC}, JIB; ${STEEL}, p.209`, spellings: 'Steel’s table: jibb.' },
    { term: 'flying jib', variants: [], definition: 'A light-weather jib set beyond the jib on the flying jibboom. From 1794.', quote: 'a sail sometimes set upon a boom, rigged out beyond the Jib-Boom', source: 'Moore 1801, JIB' },
    { term: 'fore topmast staysail', variants: ['fore top-mast stay-sail'], definition: 'The headsail inside the jib, its foot spread along the bowsprit. The heavy-weather headsail.', source: `${STEEL}, pp.209–210; ${LEVER}, p.59` },
    { term: 'fore staysail', variants: [], definition: 'A staysail on the fore preventer stay. Introduced 1773 (Lees). “Seldom used in any Ships but Men of War.”', source: `${LEVER}, p.59` },
    { term: 'main staysail', variants: [], definition: 'A triangular staysail on its own stay between main mast-head and foremast, “seldom bent in ships but at sea”. A sail for lying to.', source: `${STEEL}, p.214; ${LEVER}, p.61` },
    { term: 'main topmast staysail', variants: [], definition: 'The staysail on the main topmast preventer stay, taken in with brails and a downhauler.', source: `${STEEL}, pp.214–215; ${LEVER}, p.61` },
    { term: 'middle staysail', variants: [], definition: 'A fair-weather staysail on its own stay between the main topmast head and the fore topmast.', source: `${STEEL}, p.215; ${LEVER}, p.61` },
    { term: 'main topgallant staysail', variants: [], definition: 'A light-airs staysail on a stay spliced into the main topgallant stay.', source: `${STEEL}, p.215; ${LEVER}, p.62` },
    { term: 'mizen staysail', variants: ['mizzen staysail'], definition: 'The staysail between the mizen and main masts, on its own stay in large ships.', source: `${STEEL}, pp.215–216; ${LEVER}, p.62` },
    { term: 'mizen topmast staysail', variants: [], definition: 'A fair-weather staysail on the mizen topmast stay.', source: `${STEEL}, p.216` },
    { term: 'mizen', variants: ['mizzen', 'mizen course'], definition: 'The aftermost mast. Also the standing fore-and-aft sail on it: four-sided, loose-footed, laced to the mizen yard or gaff and to the mast, and taken in by brails.', source: `${STEEL}, p.217; ${LEVER}, p.63`, spellings: 'All the period sources: mizen. Modern: mizzen.', see: ['driver', 'spanker'] },
    { term: 'driver', variants: ['driver boom-sail'], definition: 'In 1794–1808, a large fair-weather sail set on the gaff and a boom in place of the mizen. Earlier (Falconer) a temporary sail hoisted to the mizen peak. It became the permanent sail in 1806 or 1810; Lees gives both dates.', quote: 'an oblong sail, occasionally hoisted to the mizen-peak, when the wind is very fair', source: `${FALC}, DRIVER; ${STEEL}, pp.118, 217; ${LEVER}, p.66`, see: ['spanker', 'mizen'] },
    { term: 'spanker', variants: [], definition: 'In this period another name for the driver. “Spanker” as the name of the permanent boomed sail on the mizen mast is later usage, adopted by Lees to tell the two apart.', quote: 'a name sometimes given to a ship’s Driver', source: `Moore 1801, SPANKER; ${STEEL} (“the driver, or spanker”)`, see: ['driver'] },
    { term: 'spritsail', variants: ['spritsail course', 'sprit-course'], definition: 'The square sail under the bowsprit. Still issued, but “now in many ships laid aside” (Lever).', source: `${STEEL}, pp.117, 219; ${LEVER}, p.58` },
    { term: 'sprit topsail', variants: ['spritsail-topsail', 'spritsail topsail'], definition: 'A small square sail on its own yard under the jibboom, its clews spread to the spritsail yard-arms. A light-airs sail, no longer issued from 1815 (Lees).', source: `${STEEL}, pp.197, 219; ${LEVER}, pp.41, 59`, spellings: 'Steel, Lever and Falconer: spritsail-topsail. Steel’s mast table and Lees: sprit topsail.' },
    { term: 'studding sail', variants: ['studding-sail', 'studdingsail', 'stunsail', 'stuns’l', 'stun’sail', 'steering sail'], definition: 'A light sail set outside the leech of a square sail in fair weather, on the fore and main masts only. Lower, topmast and topgallant studding sails are named from the sail they extend.', quote: 'Certain light sails extended, in moderate and steady breezes, beyond the skirts of the principal sails, where they appear as wings upon the yard-arms', source: `${FALC}, STUDDING-SAILS; ${STEEL}, pp.84, 217–219`, spellings: 'Steel, Lever, Falconer, Moore: studding sail, studding-sail or studdingsail. Stunsail, stuns’l and stun’sail appear in print only in later books (Luce; Lees). “Steering sail” is American (Totten).' },
    { term: 'lower studding sail boom', variants: ['lower studding-sail boom'], definition: 'The boom rigged out from the ship’s side on a goose-neck to spread the foot of a lower studding sail. Steel’s and Lever’s name for it.', source: `${STEEL}, p.218; ${LEVER}, p.64`, see: ['swinging boom'] },
    { term: 'swinging boom', variants: [], later: true, definition: 'The later name for the lower studding sail boom. It does not occur in Steel, Lever, Falconer or Moore; it is in Dana (1841) and is the term Lees uses.', source: 'Dana 1841', see: ['lower studding sail boom'] },
    { term: 'studding sail boom', variants: ['studding-sail boom'], definition: 'A boom that slides out along a yard through boom irons to spread the foot of the studding sail above: the topmast studding sail boom lies on the lower yard, the topgallant studding sail boom on the topsail yard.', source: `${STEEL}, pp.35, 218; ${LEVER}, p.64` },
    { term: 'studding sail yard', variants: [], definition: 'The short yard to which the head of a studding sail is bent.', source: `${STEEL}, p.40` },
    { term: 'head sails', variants: ['headsails', 'head-sails'], definition: 'The sails before the ship’s centre of rotation: those of the foremast and bowsprit. They make her fall off from the wind.', quote: 'any sail set abaft this centre, tends to make a ship stay, or come to the wind, and all before it, to make her fly off from the wind', source: `${LEVER}, p.73`, see: ['after sails'] },
    { term: 'after sails', variants: ['after-sails'], definition: 'The sails abaft the ship’s centre of rotation: those of the main and mizen masts. They bring her up to the wind.', source: `${LEVER}, p.73`, see: ['head sails'] },
    { term: 'head', variants: [], definition: 'Of a sail: its upper edge. Of a ship: the fore part, forward of the forecastle.', source: `${STEEL}, pp.210–211` },
    { term: 'foot', variants: [], definition: 'The lower edge of a sail.', source: `${STEEL}, pp.210–212` },
    { term: 'leech', variants: ['leach'], definition: 'The side edge of a square sail; the after edge of a fore-and-aft sail. The weather leech is the one towards the wind.', source: `${STEEL}, p.169` },
    { term: 'bunt', variants: [], definition: 'The middle of a square sail. Furled, it is the bulk gathered at the middle of the yard.', source: `${STEEL}, p.212` },
    { term: 'clew', variants: ['clue'], definition: 'A lower corner of a square sail; the after lower corner of a fore-and-aft sail.', source: `${STEEL}, pp.210–212`, spellings: 'Steel’s text and Falconer: clue. Lever and Steel’s tables: clew.' },
    { term: 'tack', variants: ['tacks'], definition: 'Three things. The rope that hauls the weather clew of a course forward and down. The lower fore corner of a fore-and-aft sail, and the rope at the outer lower corner of a studding sail. And the side from which the wind comes: on the starboard tack the wind is on the starboard side.', quote: 'Ropes used to confine the foremost lower corners of courses', source: `${STEEL}, p.176; ${FALC}, TACK`, see: ['tacking', 'sheet'] },
    { term: 'sheet', variants: ['sheets'], definition: 'The rope at the clew of a sail that holds it out against the wind. On a course it hauls the lee clew aft; on a topsail it hauls the clew down to the yard-arm below.', quote: 'A rope or tackle fastened to the clues of sails, to retain them in any direction', source: `${STEEL}, p.174` },
    { term: 'earing', variants: ['earring', 'earings'], definition: 'A small rope that lashes an upper corner of a sail to the yard-arm. Head earings bend the sail; reef earings haul a reef band’s end out to the yard-arm.', quote: 'Small ropes employed to fasten the upper corners of sails', source: `${STEEL}, p.165; ${FALC}, EARINGS`, spellings: 'Steel, Lever and Falconer: earing.' },
    { term: 'reef', variants: ['reefs', 'reefing'], definition: 'A strip across the head of a sail that can be tied up to the yard to make the sail smaller. Topsails have two to four.', quote: 'Sails, according to their sizes, have from one to four reefs.', source: `${STEEL}, p.172; ${LEVER}, pp.54, 83` },
    { term: 'reef-band', variants: ['reef band'], definition: 'The strengthened band of canvas across a sail in which the reef points are fixed.', source: `${LEVER}, p.54` },
    { term: 'reef points', variants: ['points'], definition: 'The short plaited lines through a reef band, tied round the yard with reef knots to hold a reef.', quote: 'short pieces of braided cordage, plaited together as gaskets are', source: `${STEEL}, p.184` },
    { term: 'bag-reef', variants: [], definition: 'The fourth, or lowest, reef of a topsail.', quote: 'A BAG-REEF is the fourth, or lower, reef of a topsail', source: `${STEEL}, p.172` },
    { term: 'close-reefed', variants: ['close reefed'], definition: 'With the last reef the sail has taken in: the third or fourth on a topsail.', source: `${LEVER}, pp.86–87` },
    { term: 'reef tackle', variants: ['reef-tackle'], definition: 'The tackle that hauls the leech of a topsail up to the yard-arm so that a reef can be taken. Topsails only in this period.', quote: 'are used to draw the extremities of the reefs close up to the yard-arms, for reefing the sail', source: `${STEEL}, p.177; ${LEVER}, p.38` },
    { term: 'bowline', variants: ['bow-line'], definition: 'A rope from the weather leech of a square sail leading forward, to hold the leech steady when close-hauled. Only the weather one is in use.', quote: 'used to brace sideways, or close-haul to the wind, the weather, or windward, leeches of the sails forward; which are kept steady by the tension of the bowline', source: `${STEEL}, p.169; ${FALC}, BOWLINE`, see: ['bridle'] },
    { term: 'bridle', variants: ['bridles', 'bowline bridle'], definition: 'One of the short legs by which a bowline is made fast to two or three cringles on the leech.', source: `${STEEL}, p.211; ${LEVER}, pp.54–57` },
    { term: 'bowline tackle', variants: ['bowline-tackle'], definition: 'A long tackle hooked to the lizard on the main bowline to heave it taut before it is belayed.', source: `${STEEL}, pp.211–212` },
    { term: 'buntline', variants: ['bunt-line'], definition: 'A rope from the foot of a square sail up the fore side to the yard, to haul the foot up. On a course there are two legs a side on one fall.', quote: 'BUNTLINES are ropes fastened to the foot of square sails, to haul them up to their yards', source: `${STEEL}, p.169; ${FALC}, BUNTLINES` },
    { term: 'leech-line', variants: ['leechline', 'leech line'], definition: 'A rope from the leech of a course up to the yard, to haul the side of the sail in and up. Steel’s table lists them for a 74’s topsails as well, but no source gives that lead.', quote: 'LEECH-LINES are ropes used to truss up the sails', source: `${STEEL}, p.169` },
    { term: 'slab-line', variants: ['slabline', 'slab line'], definition: 'A rope up the after side of a course to lift its foot for a moment.', quote: 'a rope used to truss up the foot of the main and fore courses occasionally, for the pilot or master to look forward underneath, as the ship advances', source: `${STEEL}, p.169; ${FALC}, SLAB-LINE` },
    { term: 'spilling line', variants: ['spilling-line'], definition: 'A rope passed right round a sail to gather it bodily in heavy weather. Rigged for the occasion.', source: `${STEEL}, p.169` },
    { term: 'clewline', variants: ['clue-line', 'clew-line', 'clueline'], definition: 'The rope that hauls the clew of a topsail, topgallant or spritsail up to its yard.', quote: 'CLUE-LINES are similar to the clue-garnets, and are used to square sails in general; whereas clue-garnets are confined to the main and fore courses', source: `${STEEL}, p.169`, spellings: 'Steel and Falconer: clue-line. Lever: clew-line. Modern: clewline.', see: ['clew-garnet'] },
    { term: 'clew-garnet', variants: ['clue-garnet', 'clewgarnet'], definition: 'The clewline of a course: a whip from the yard to a block at the clew, to haul the clew up.', quote: 'Tackles connected to the clues of main and fore courses, to truss the sail up to the yard', source: `${STEEL}, p.164`, spellings: 'Steel and Falconer: clue-garnet. Lever: clew-garnet.' },
    { term: 'gasket', variants: ['gaskets'], definition: 'A plaited line that binds a furled sail to its yard: yard-arm gaskets, quarter gaskets and the bunt gasket.', quote: 'Braided cordage used to confine the sail to the yard, when furled', source: `${STEEL}, p.167; ${FALC}, GASKET` },
    { term: 'harbour gaskets', variants: ['harbor gaskets'], later: true, definition: 'Short, broad, blacked gaskets for showing off a neat furl in port. The term is from Smyth (1867); sea gaskets are the long ones wound round and round.', quote: 'Broad, but short and well-blacked gaskets, placed at equal distances on the yard, for showing off a well-furled sail in port', source: 'Smyth 1867, HARBOUR-GASKETS' },
    { term: 'roband', variants: ['rope-band', 'ropeband', 'robands'], definition: 'A short plaited line through an eyelet in the head of a sail, tying it to the yard.', quote: 'Braided cordage, used to fasten the heads of sails to their respective yards', source: `${STEEL}, p.172; ${FALC}, ROBANDS`, spellings: 'Steel: rope-bands. Falconer: robands, or rope-bands.' },
    { term: 'jackstay', variants: ['jack-stay', 'jack stay'], later: true, definition: 'A rope or rod along the top of a yard to which the sail is bent. On yards it dates from 1811 (Lees) and appears in Lever only in the 1819 appendix; in this period sails are bent round the yard itself. Lever does use “jack stay” for a rope up a mast or along the jibboom on which something travels.', source: `${LEVER}, p.54 and Appendix` },
    { term: 'skin', variants: [], definition: 'In furling, the part of the head of the sail left hanging to be drawn over the rest as a cover.', quote: 'leaving enough of the head part… hanging in a bight (which is called a Skin), to cover the folds', source: `${LEVER}, p.53` },
    { term: 'passaree', variants: [], definition: 'A rope that hauls the weather clew of the foresail down to the cathead when the wind is free.', quote: 'Any rope fastened round the cat-head and fore-tack, to keep tight the leech of the sail in light winds', source: `${STEEL}, p.171; ${LEVER}, p.80` },
    { term: 'brails', variants: ['brail'], definition: 'Ropes from the after leech of the mizen, driver or a staysail to the gaff and mast, by which the sail is gathered up without lowering it: throat, middle and peak brails.', source: `${STEEL}, pp.217, 336; ${LEVER}, pp.63, 85` },
    { term: 'fancy line', variants: [], definition: 'A line that lifts the slack lee brails of the mizen clear of the sail.', source: `${STEEL}, p.217; ${LEVER}, p.63` },
    { term: 'downhauler', variants: ['downhaul', 'down-haul', 'downhaller', 'down-hauler'], definition: 'A rope that hauls a staysail or jib down its stay, or a studding-sail yard down to its tack.', source: `${STEEL}, pp.209, 335; ${LEVER}, p.60`, spellings: 'Steel and Lever: downhauler. Steel’s tables: downhaller. Steel p.335: down-haul.' },
    { term: 'outhauler', variants: ['outhaul', 'out-hauler', 'out-haller'], definition: 'A rope that hauls the tack or clew of a sail out along a spar: the jib’s traveller out along the jibboom, the driver’s clew out along the boom.', source: `${STEEL}, pp.209, 217; ${LEVER}, p.60`, spellings: 'Steel: outhauler, out-haller. Lever: out-hauler.' },
    { term: 'inhauler', variants: ['inhaul', 'in-hauler'], definition: 'The rope that hauls the jib’s traveller in along the jibboom.', source: `${STEEL}, p.209` },
    { term: 'deck sheet', variants: [], definition: 'The long leg of a topmast studding sail’s sheet, led down to the forecastle; by it the sail is gathered in.', source: `${STEEL}, p.335; ${LEVER}, p.83`, see: ['yard sheet'] },
    { term: 'yard sheet', variants: ['short sheet'], definition: 'The sheet of a topmast studding sail that hauls its inner clew out and down to the lower yard. Later manuals call it the short sheet.', source: `${LEVER}, pp.64, 80` },
    { term: 'boom tackle', variants: ['in-and-out jigger'], definition: 'The tackle by which a topmast studding-sail boom is launched out along the lower yard in a man-of-war. “In-and-out jigger” is the later name (Totten, Luce).', source: `${STEEL}, p.218; ${LEVER}, p.64` },
    { term: 'heel lashing', variants: [], definition: 'The lashing that holds the inner end of a studding-sail boom to its yard.', source: `${LEVER}, pp.64, 82` },
    { term: 'tripping line', variants: [], later: true, definition: 'A line to haul the outer clew of a lower studding sail up in taking it in. Not in Steel; in the later manuals (Dana “clewline”, Nares “tripping line”).', source: 'Nares 1862; Dana 1841' },
    { term: 'water-holes', variants: [], definition: 'Holes near each clew of the spritsail to let out the water it scoops up.', quote: 'to let the Water off, that it may not lodge in the Bag of the Sail', source: `${LEVER}, p.58` },
    { term: 'lacing', variants: [], definition: 'A line passed spirally through eyelets to bend a sail to a spar: the mizen to its gaff and mast.', source: `${STEEL}, p.217` },

    // ---- Standing rigging -----------------------------------------------------
    { term: 'standing rigging', variants: [], definition: 'The fixed ropes that hold the masts and bowsprit up: shrouds, stays, backstays, bobstays. Tarred, and set up once.', source: `${STEEL}, pp.194–208` },
    { term: 'running rigging', variants: [], definition: 'The ropes that move: everything that hoists, lowers, swings or trims a yard or sail.', source: `${STEEL}, pp.202–219` },
    { term: 'shrouds', variants: ['shroud'], definition: 'The heavy ropes from a mast-head down to the ship’s side (or to the rim of the top), supporting the mast sideways and from abaft.', source: `${STEEL}, p.197; ${LEVER}, p.22` },
    { term: 'swifter', variants: ['swifters'], definition: 'The odd shroud each side, over and above the pairs.', quote: 'the after shrouds on each side of the main and fore masts: they are above all the other shrouds', source: `${STEEL}, rigging terms` },
    { term: 'ratlines', variants: ['ratlings', 'ratling'], definition: 'The small lines hitched across the shrouds as steps.', source: `${STEEL}, p.198`, spellings: 'Steel: ratlings; the verb is “rattled”.' },
    { term: 'futtock shrouds', variants: ['futtock-shrouds'], definition: 'The short shrouds from the rim of a top down and inward to the lower shrouds. They carry the pull of the topmast shrouds into the lower rigging.', source: `${STEEL}, pp.199–200; ${LEVER}, p.28` },
    { term: 'futtock staff', variants: ['futtock stave', 'futtock-staves'], definition: 'A served rope seized across the lower shrouds below the top, to which the futtock shrouds and catharpins are secured.', source: `${STEEL}, p.198` },
    { term: 'catharpins', variants: ['cat-harpings', 'catharpin legs', 'cross catharpins'], definition: 'Short ropes that draw the lower shrouds in toward each other at the futtock staves, so the yard can be braced up sharper.', quote: 'Short ropes, to keep the lower shrouds in tight, after they are braced in by swifters, and to afford room to brace the yards sharp', source: `${STEEL}, rigging terms`, spellings: 'Steel and Lever: catharpins. Falconer and Moore: cat-harpings.' },
    { term: 'Bentinck shrouds', variants: [], definition: 'Extra shrouds for heavy weather, from the futtock staves across to the chains on the opposite side.', source: `${STEEL}, pp.230–231` },
    { term: 'channel', variants: ['channels', 'chain-wale'], definition: 'A thick plank standing out from the ship’s side abreast each mast, to spread the shrouds. The lower blocks of the topsail halliards hook to eye-bolts in it.', quote: 'to extend the shrouds from each other, and from the head of the masts', source: `${STEEL}, rigging terms; p.205` },
    { term: 'chains', variants: ['chain-plates'], definition: 'The iron plates bolted to the ship’s side that hold the lower deadeyes; loosely, the channels. A man “in the chains” is standing on the channel.', source: `${STEEL}, rigging terms` },
    { term: 'stay', variants: ['stays'], definition: 'A rope that supports a mast from forward. Each leads to the next mast forward or to the bowsprit.', source: `${STEEL}, pp.200–201`, see: ['in stays'] },
    { term: 'preventer stay', variants: ['spring stay', 'preventer-spring-stay'], definition: 'A second, lighter stay beside each stay, to take its place if it is shot away. Lever calls the same rope a spring stay.', quote: 'subordinate stays to support their respective stays, and supply their places in case of any accident', source: `${STEEL}, rigging terms; ${LEVER}, p.23`, spellings: 'Steel and the Navy’s tables: preventer stay. Lever: spring stay. Steel’s glossary: preventer-spring-stay.' },
    { term: 'backstay', variants: ['backstays', 'back-stay', 'standing backstay', 'shifting backstay', 'preventer backstay'], definition: 'A rope from a topmast or topgallant mast head down to the channel, supporting the mast from abaft. Standing backstays are permanent; breast and shifting backstays are set up on the weather side as needed.', quote: 'stays which support the topmasts and topgallant masts from aft… and assist the shrouds when strained by a press of sail', source: `${STEEL}, rigging terms; ${FALC}, BACK-STAYS` },
    { term: 'breast backstay', variants: ['breast back-stay'], definition: 'A backstay abreast the mast, set up with a runner and tackle on the weather side when the ship is on a wind and let go to leeward. It is shifted at every tack.', quote: 'for the lateral support of the Topmast… being for temporary use, they are not set up with Dead Eyes', source: `${LEVER}, p.27` },
    { term: 'travelling backstay', variants: ['traveling backstay'], definition: 'A backstay on a strap round the topmast just above the yard, rigged when the topsail is double-reefed so that the support is where the yard now pulls.', source: `${STEEL}, p.235; ${LEVER}, p.85` },
    { term: 'bobstay', variants: ['bob-stay'], definition: 'A stay from the bowsprit down to the cutwater, holding the bowsprit down against the pull of the fore stays.', quote: 'to draw down, and keep steady the bowsprit, to counteract the force of the stays of the fore-mast, which draw it upwards', source: `${STEEL}, p.195` },
    { term: 'gammoning', variants: [], definition: 'The lashing of many turns that binds the bowsprit down to the knee of the head.', source: `${STEEL}, p.194` },
    { term: 'burton pendents', variants: ['pendents of tackles', 'runner pendents', 'tackle pendents'], definition: 'Short pendents put over a mast-head before the shrouds, with a thimble hanging each side for a tackle. At the lower mast-heads they are the pendents of tackles (Lever: runner pendents); at the topmast heads the burton pendents.', source: `${STEEL}, pp.197, 199`, spellings: 'Steel: pendents of tackles. Lever: runner pendents. Steel’s tables: pendants.' },

    { term: 'bowsprit shrouds', variants: [], definition: 'A rope each side from the bow to a collar on the bowsprit, supporting it sideways.', quote: 'The shrouds are to fortify the bowsprit, as the fore-mast and upper part of the main-mast are stayed and supported by the bowsprit', source: `${STEEL}, p.195` },
    { term: 'staysail stay', variants: [], definition: 'A light stay rigged for a staysail to set on, where the sail does not hang on a mast’s own stay: the jib stay, the middle staysail stay, the mizen staysail stay.', source: `${STEEL}, pp.209–216` },
    { term: 'cabled', variants: ['cable-laid'], definition: 'Of rope: made of three ropes laid up together, as an anchor cable is. Tacks, the heaviest sheets and the lower shrouds of a 74 are cabled in Steel’s table. The definition is general knowledge; the table gives only the word.', source: `Steel’s table of rigging for a 74` },

    // ---- Belaying ----------------------------------------------------------
    { term: 'belay', variants: ['belaying'], definition: 'To make a rope fast with turns round a cleat, pin, kevel or the cross-piece of a pair of bitts. The word belongs to the lighter running rigging.', quote: 'Fastening a rope, by giving it several cross turns alternately round each end, of a cleat, pin, &c.', source: `${STEEL}, p.162; ${FALC}, BELAY` },
    { term: 'bitts', variants: ['bits', 'bitt'], definition: 'A pair of stout posts with a cross-piece, at the foot of a mast. The posts have sheaves near the deck through which heavy falls are led; lighter ropes belay round the cross-piece. This is the fitting at the foot of a mast in this period.', source: `${STEEL}, pp.162, 206, 212`, spellings: 'Steel writes both bitts and bits.', see: ['topsail-sheet bitts', 'jeer bitts'] },
    { term: 'cross-piece', variants: ['cross piece'], definition: 'The timber across a pair of bitts, round which ropes are belayed.', source: `${STEEL}, pp.206, 210` },
    { term: 'topsail-sheet bitts', variants: ['topsail sheet bitts'], definition: 'The bitts at a mast through whose sheaves the topsail sheets and the clew-garnets of the course below come. The main ones are on the upper deck at the fore edge of the quarterdeck, where Steel says they “tenon into the fore-mast-beam of the quarter-deck”.', source: `${STEEL}, p.162` },
    { term: 'jeer bitts', variants: ['jear bitts'], definition: 'The bitts by a lower mast named for the jeers. That the jeer falls belay there is the reading of the name; no source read says so.', quote: 'the FORE-JEER and TOPSAIL-SHEET bitts are situated on the forecastle and round the fore-mast', source: `${STEEL}, p.162` },
    { term: 'fore-brace bitts', variants: ['brace bitts'], definition: 'The bitts on the quarterdeck just abaft the mainmast, through which the fore braces lead.', quote: 'through a sheave-hole in the bitts, at the fore part of the quarter-deck', source: `${STEEL}, pp.202, 216` },
    { term: 'main-top-bowline bitts', variants: ['maintop-bowline-bitts'], definition: 'Bitts on the forecastle that Steel names for the main topsail bowlines and several staysail and studding-sail ropes. The deck plans show no third set on the forecastle, so this is probably another name for the bitts abaft the foremast (inference).', source: `${STEEL}, pp.209, 213–214, 218` },
    { term: 'riding bitts', variants: [], definition: 'The largest bitts, on the lower deck forward, for the anchor cables. Not a belaying point for running rigging.', source: `${STEEL}, glossary` },
    { term: 'gallows bitts', variants: [], definition: 'Raised bitts for carrying spare spars. Not mentioned by Steel or Lever for ships of this date; on a 74 the spare spars lay on the boat skids.', source: `${STEEL}, p.232` },
    { term: 'cleat', variants: ['cleats'], definition: 'A piece of wood with two arms, nailed or bolted to the side, a mast, the belfry or a cathead, to belay a rope to. Also a wedge nailed on a spar to stop rigging slipping.', source: `${STEEL}, passim` },
    { term: 'range cleat', variants: ['range-cleat'], definition: 'A very large cleat bolted to the ship’s side on the upper deck in the waist, for the tacks and sheets of the courses.', quote: 'Large cleats, with two arms, bolted in the waist of ships, to belay the tacks and sheets to', source: `${STEEL}, glossary; pp.210–211` },
    { term: 'shroud cleat', variants: [], definition: 'A cleat with a hollowed back, seized to a lower shroud near the deck.', quote: 'belay round a cleat lashed to the shrouds near the deck', source: `${STEEL}, p.215` },
    { term: 'kevel', variants: ['cavel', 'kevels'], definition: 'A pair of crooked timbers against the ship’s side whose heads branch like horns, for belaying the heaviest ropes. Modern writers use kevel and cavel for different shapes and do not agree.', quote: 'Two crooked pieces of timber, whose lower ends rest in a step or foot nailed to the ship’s sides; the heads branch out like horns', source: `${STEEL}, glossary; ${FALC}, KEVELS` },
    { term: 'staghorn', variants: [], later: true, definition: 'A modern writers’ word (Longridge, Lavery) for a U- or V-shaped horned belaying timber. Steel, Lever and Falconer do not use it.', source: 'Reported from Longridge and Lavery at second hand' },
    { term: 'timberhead', variants: ['timber-head', 'timber head'], definition: 'The head of a frame timber standing above the deck at the ship’s side, used to belay to.', source: `${STEEL}, pp.209, 214, 216, 218` },
    { term: 'belaying pin', variants: ['pin', 'belaying-pin'], definition: 'A turned wooden pin, or an iron one, set in a rack or rail to belay small ropes to. Well attested from the 1750s; what is later is the long rail of pins inside the bulwark.', quote: 'BELAYING-PINS are wooden pins, turned in a lathe, made of ash, 16 inches long', source: `${STEEL}, block-making, p.160; glossary, p.171` },
    { term: 'rack', variants: ['pin rack', 'shroud-rack', 'shroud rack'], definition: 'A short plank with holes for belaying pins, seized across the lower shrouds or fixed over the bowsprit. Falconer’s rack is a frame of sheaves at the bowsprit that sorts the ropes.', quote: 'A short thin plank, with holes made through it, containing a number of belaying-pins, used instead of cleats: it is seized to the shrouds, and nailed over the bowsprit or windlass', source: `${STEEL}, p.171; ${FALC}, RACK`, see: ['rack a tackle'] },
    { term: 'pin rail', variants: ['pinrail'], later: true, definition: 'A long rail of belaying pins bolted inside the bulwark. Not evidenced for this period; Lees’s first example is reported to be a frigate of about 1810, and the long continuous rail belongs to later merchant ships.', source: 'Lees, reported at second hand' },
    { term: 'fife-rail', variants: ['fife rail', 'fiferail'], definition: 'In this period, the open rail along the top of the quarterdeck and poop sides, with pins and cleats in it. Not a rail round a mast.', quote: 'a pin in the fife-rail', source: `${STEEL}, pp.207–208, 217; ${LEVER}`, see: ['rough-tree rail', 'mast-foot fife rail'] },
    { term: 'mast-foot fife rail', variants: ['fife rail round a mast'], later: true, definition: 'A free-standing rail of belaying pins round the foot of a mast. This is the later sense of “fife rail”; the sources for it are of the 1880s. In this period the fitting at the foot of a mast is a set of bitts.', source: 'Absent from Steel 1794, Lever 1808 and Falconer 1769', see: ['fife-rail', 'bitts'] },
    { term: 'rough-tree rail', variants: ['rough tree rail', 'hand-rail'], definition: 'Steel’s other names for the open rail along the quarterdeck and poop sides.', quote: 'A rail, breast high, along the sides of the poop and quarter-deck', source: `${STEEL}, glossary` },
    { term: 'breast-rail', variants: ['breast-work', 'breastwork', 'breast rail'], definition: 'The rail on stanchions across the fore end of the quarterdeck and the after end of the forecastle. Buntline and leech-line falls are belayed round it.', quote: 'The rails and stantions on the foremost end of the quarter-deck and poop', source: `${STEEL}, p.163; ${LEVER}` },
    { term: 'boat skids', variants: ['boat-skid', 'boatskid', 'skids'], definition: 'Beams across the waist from gangway to gangway that carry the boats and spare spars. Ropes belay to them and to iron pins in them.', quote: 'round an iron pin in the boat-skid', source: `${STEEL}, pp.204, 215` },
    { term: 'belfry', variants: ['bellfry'], definition: 'The housing of the ship’s bell at the after edge of the forecastle. It has a cleat each side for the fore topgallant braces.', source: `${STEEL}, p.206` },
    { term: 'gangway', variants: ['gangways'], definition: 'The walkway along each side of the waist, joining the forecastle to the quarterdeck.', source: 'Admiralty draughts' },
    { term: 'waist', variants: [], definition: 'The part of the ship between the forecastle and the quarterdeck, open down to the upper deck.', source: `${STEEL}, pp.210–211` },
    { term: 'forecastle', variants: ['fore-castle'], definition: 'The short deck over the fore part of the upper deck, round the foremast.', source: `${STEEL}, passim` },
    { term: 'quarterdeck', variants: ['quarter-deck'], definition: 'The deck over the after part of the upper deck, from just before the mainmast aft.', source: `${STEEL}, passim` },
    { term: 'poop', variants: [], definition: 'The short deck over the after end of the quarterdeck. The mizen mast comes up through it.', source: 'Admiralty draughts' },
    { term: 'upper deck', variants: [], definition: 'In a 74, the upper of the two gun decks, a level below the forecastle and quarterdeck. Course tacks and sheets belay here.', source: `${STEEL}, pp.210–211` },
    { term: 'taffrail', variants: ['taffarel'], definition: 'The rail across the stern at the after end of the poop.', source: `${STEEL}, pp.204, 217`, spellings: 'Steel and Lever: taffarel.' },
    { term: 'quarter-piece', variants: ['quarter piece'], definition: 'The timber at the after corner of the ship’s side. The standing part of the main brace is clinched to an eye-bolt in it.', source: `${STEEL}, p.202` },
    { term: 'gunwale', variants: [], definition: 'The top edge of the ship’s side.', source: `${STEEL}, p.202` },
    { term: 'stopper', variants: ['stoppers'], definition: 'A short rope made fast at one end and wound round a heavy rope to hold it while it is belayed. Tacks, sheets, topsail sheets and jeers have them.', quote: 'FORE-TACK, and SHEET, STOPPERS, are for securing the tacks and sheets, till belayed', source: `${STEEL}, pp.176, 235` },
    { term: 'coil', variants: ['coil down'], definition: 'To lay the loose part of a rope in regular turns, so that it stows clear and will run.', quote: 'Rope laid in regular folds for the convenience of stowage, and hanging upon cleats, to prevent its being entangled', source: `${STEEL}, p.164; ${FALC}, COIL` },
    { term: 'overhaul', variants: ['overhauling'], definition: 'To pull slack through a block or tackle by hand, the opposite way to hauling, so that the rope runs free.', quote: 'Extending the several parts of a tackle, or ropes, connected to blocks or dead-eyes, to any distance required', source: `${STEEL}, p.170` },
    { term: 'ease off', variants: ['veer away', 'ease away'], definition: 'To slacken a rope gradually, under control.', quote: 'EASE-OFF, or VEER-AWAY. To slacken a rope gradually', source: `${STEEL}, glossary` },
    { term: 'bowse', variants: ['bouse', 'bowsing'], definition: 'To haul on a tackle.', quote: 'Hauling or pulling upon a rope or fall of a tackle', source: `${STEEL}, glossary`, spellings: 'Steel: bowsing. Lever: bowsed, boused.' },
    { term: 'sway', variants: ['sway up'], definition: 'To hoist by hauling down on a rope: a yard is swayed up by its jeers.', quote: 'To haul down upon a rope', source: `${STEEL}, glossary; ${LEVER}, p.35` },
    { term: 'hand-tight', variants: ['hand-taut'], definition: 'A term in Steel’s glossary; the notes do not give his definition. The plain sense is as tight as hands alone can pull.', source: `${STEEL}, glossary` },
    { term: 'rack a tackle', variants: ['racking'], definition: 'To seize the parts of a fall together so that the tackle holds what has been gained.', source: `${STEEL}, glossary` },
    { term: 'fleet', variants: ['fleeting'], definition: 'To shift a tackle that has come block-and-block so that it can be hauled on again.', source: `${STEEL}, glossary` },
    { term: 'block-and-block', variants: ['block and block'], definition: 'Of a tackle: hauled until its two blocks meet, so that no more can be gained.', source: `${STEEL}, glossary` },
    { term: 'swig off', variants: ['swigging off'], definition: 'To pull sideways on the middle of a taut rope to gain a little more.', quote: 'Pulling upon the middle of a tight rope that is made fast at both ends', source: `${STEEL}, glossary` },
    { term: 'let fly', variants: [], definition: 'To let a rope go all at once and leave it to run. Lever’s verb for the halliards when reefing.', quote: 'the Halliards are let fly', source: `${LEVER}, p.83` },
    { term: 'settle', variants: [], definition: 'To lower a yard a little by easing its halliards.', quote: 'the yards are settled a little, to ease the strain in casting off the points', source: `${LEVER}, p.92` },
    { term: 'round in', variants: ['rounded in'], definition: 'To haul in on a brace, especially the weather brace.', quote: 'the Weather Brace rounded in, to spill the Sail', source: `${LEVER}, p.83` },
    { term: 'check', variants: [], definition: 'To ease a rope a little, or to stop it running. To check a bowline is to slacken it when the wind draws aft.', quote: 'To check the Bowline, is to slacken it, when the wind becomes large', source: `${FALC}, BOWLINE` },
    { term: 'start', variants: [], definition: 'To ease a rope from where it is made fast: “the weather sheet started”.', source: `${LEVER}, p.86` },
    { term: 'sheet home', variants: ['haul home'], definition: 'To haul the sheets of a topsail or topgallant until the clews are out at the yard-arms below.', quote: 'The lee Sheets of either Topsails or Top-Gallant Sails, are always hauled home first', source: `${LEVER}, p.84` },
    { term: 'board', variants: ['aboard', 'on board', 'haul aboard'], definition: 'To haul a tack down: “the main tack on board”. Also the stretch a ship sails on one tack.', quote: 'ABOARD MAIN TACK! The order to draw the lower corner of the mainsail down to the chess-tree', source: `${STEEL}, sea terms` },
    { term: 'taut', variants: ['taught'], definition: 'Tight.', source: `${LEVER}, passim`, spellings: 'Lever: taught.' },
    { term: 'gear', variants: ['geer'], definition: 'The ropes belonging to a sail or spar, collectively.', quote: 'the Geer coiled up', source: `${LEVER}, pp.83–87`, spellings: 'Lever: geer.' },
    { term: 'reeve', variants: ['rove', 'reeved'], definition: 'To pass a rope’s end through a block, thimble or hole. Past tense rove (Steel and Lever also write reeved).', source: `${STEEL}, passim` },
    { term: 'bend', variants: ['bent', 'bending'], definition: 'To make one rope fast to another or to a spar or ring; to make a sail fast to its yard.', source: `${STEEL}, pp.210–213` },
    { term: 'clap on', variants: ['clapped on'], definition: 'To put a tackle, stopper or more hands on to a rope.', source: `${STEEL}, p.235; ${LEVER}, p.86` },
    { term: 'trice', variants: ['trice up'], definition: 'To haul something up out of the way with a light line. “Trice up” as an order lifts the heels of the studding-sail booms so men can lie out on the yard; as a spoken order it is found from 1836.', source: `${STEEL}, p.202; Glascock 1836` },
    { term: 'hand', variants: ['handed'], definition: 'To take a sail in and furl it.', source: `${LEVER}, pp.84–86` },
    { term: 'furl', variants: ['furling'], definition: 'To roll a sail up on its yard and bind it with gaskets.', source: `${LEVER}, p.53` },
    { term: 'furling in a body', variants: [], definition: 'A harbour way of furling a topsail, with the bulk gathered into the top so the yard looks thin. The usual way was “furling in the bunt”.', quote: 'a particular method of rolling up a top-sail only practised in harbour, and is performed by gathering all the loose part of the sail into the top about the heel of the top-mast', source: 'Moore 1801 (1805 printing), FURLING' },
    { term: 'loose', variants: ['loosing'], definition: 'To cast off the gaskets of a furled sail so that it can be set or dried.', source: `${STEEL}, sea terms` },
    { term: 'clew up', variants: ['clue up'], definition: 'To haul the clews of a sail up to the yard by the clew-lines or clew-garnets.', source: `${LEVER}, pp.84–87` },
    { term: 'clew down', variants: [], later: true, definition: 'To haul a topsail yard down by its clew-lines with the sheets fast, for reefing. The phrase is from the later American manuals; Lever describes the action without it.', source: 'Totten 1862' },
    { term: 'brail up', variants: [], definition: 'To gather a mizen, driver or staysail in with its brails.', source: `${STEEL}, p.336` },
    { term: 'spill', variants: [], definition: 'To empty a sail of wind so that it can be handled.', quote: 'If the Buntlines be kept fast when the Halliards are let go, they assist in spilling the Sail', source: `${LEVER}, p.83` },
    { term: 'shiver', variants: ['shivering'], definition: 'To brace a yard so that the wind blows along the sail and it neither draws nor backs.', source: `${LEVER}, p.79` },
    { term: 'aback', variants: ['a-back', 'back'], definition: 'With the wind on the fore side of a sail, pressing it against the mast and driving the ship astern.', source: `${LEVER}, pp.74, 94` },
    { term: 'fill', variants: ['full'], definition: 'To brace a yard so that the wind is on the after side of the sail and it draws.', source: `${STEEL}, pp.327–328` },
    { term: 'box off', variants: ['boxing off'], definition: 'To throw the ship’s head off the wind by backing the head yards, when she has come up into the wind unintended.', source: `${LEVER}, p.78` },
    { term: 'flat in', variants: ['flatting in', 'flatten in'], definition: 'To haul the head sheets flat to make her fall off.', source: `${LEVER}, p.78` },
    { term: 'brace up', variants: ['brace sharp', 'sharp up'], definition: 'To swing the yards as far fore and aft as they will go, for sailing close-hauled.', quote: 'To brace the yards to a position, in which they will make the smallest possible angle with the keel, for the ship to have head-way', source: `${STEEL}, sea terms (To BRACE SHARP)` },
    { term: 'brace in', variants: [], definition: 'To haul in the weather braces, bringing the yards nearer square.', source: `${LEVER}, p.79` },
    { term: 'brace to', variants: ['bracing to'], definition: 'In tacking, to haul on the weather fore topsail brace so that the sail catches aback sooner. Lever lists it as an error, because it kills headway, except in a river or narrow channel.', source: `${LEVER}, pp.76–77` },
    { term: 'square', variants: ['square the yards'], definition: 'Of yards: at right angles to the keel, and level.', quote: 'To brace the yards, so as to hang at right angles with the keel', source: `${STEEL}, sea terms` },

    // ---- Manoeuvres, wind and helm ----------------------------------------
    { term: 'tacking', variants: ['to tack', 'going about', 'about ship', 'staying'], definition: 'Turning the ship’s head through the wind to bring the wind on the other side.', source: `${LEVER}, pp.76–77; ${FALC}, TACK`, see: ['wearing', 'in stays'] },
    { term: 'in stays', variants: ['stays', 'staying', 'miss stays'], definition: 'In the act of tacking. A ship that fails to come round misses stays.', quote: 'The cause of her missing stays is the sea, which boxes her head off again', source: `${LEVER}, p.93` },
    { term: 'wearing', variants: ['veering', 'ware', 'to wear', 'to veer'], definition: 'Turning the ship’s stern through the wind to bring the wind on the other side. It loses ground to leeward.', source: `${LEVER}, p.79; ${FALC}, VEERING; ${STEEL}, p.321`, spellings: 'Lever: ware, wearing. Steel and Falconer: veering. Both are period.' },
    { term: 'box-hauling', variants: ['boxhauling', 'box-haul'], definition: 'A way of wearing in little room: the ship is thrown up into the wind, driven astern with the after yards square and the head yards aback, and pivots on her heel.', quote: 'A particular method of veering a ship, when the swell of the sea renders tacking impracticable', source: `${STEEL}, sea terms; ${LEVER}, pp.93, 95` },
    { term: 'club-hauling', variants: ['club-haul'], definition: 'Tacking on a lee shore by letting go the lee anchor as she comes head to wind, to drag her head round, and then cutting the cable.', quote: 'A method of tacking a ship when it is expected she will miss stays on a lee-shore', source: `${STEEL}, p.325; ${LEVER}, p.95` },
    { term: 'heaving to', variants: ['heave to', 'lying to', 'lying-to', 'bring to'], definition: 'Stopping the ship by setting sails to work against each other, usually one topsail aback.', quote: 'LYING-TO is the art of disposing the sails in such a manner, that, counteracting each other, they render the ship as it were, for a time, immoveable', source: `${STEEL}, p.325; ${LEVER}, p.94` },
    { term: 'a-try', variants: ['trying', 'a-hull'], definition: 'Lying to in a gale under very little sail or none. A-hull is with every sail furled and the helm lashed a-lee.', quote: 'A-HULL. The situation of a ship, when all her sails are furled and her helm is lashed to the lee side', source: `${STEEL}, sea terms; p.330` },
    { term: 'scudding', variants: ['scud'], definition: 'Running before a gale.', source: `${LEVER}, p.90` },
    { term: 'close-hauled', variants: ['by the wind', 'on a wind'], definition: 'Sailing as near the wind as the ship will lie, about six points from it, with the yards braced sharp up and the bowlines hauled.', quote: 'The course of a ship as near as possible to the direction of the wind, which is generally within six points of it', source: `${STEEL}, sea terms (BY THE WIND); ${FALC}, CLOSE-HAULED` },
    { term: 'full and by', variants: ['full-and-by'], definition: 'Close-hauled with the sails kept just full: neither too near the wind nor off it.', quote: 'neither to steer too nigh the direction of the wind, nor to deviate to leeward', source: `${FALC}, FULL AND BY` },
    { term: 'large', variants: ['going large', 'free'], definition: 'With the wind further aft than close-hauled. “One point free” is one point further off the wind than close-hauled, which is seven points from the wind itself.', source: `${LEVER}, pp.75, 80` },
    { term: 'flowing sheets', variants: [], definition: 'Steel’s term for the trim with the wind a little free: sheets eased, bowlines let go.', source: `${STEEL}, sea terms` },
    { term: 'before the wind', variants: ['right aft'], definition: 'With the wind dead astern and the yards square.', source: `${LEVER}, p.82` },
    { term: 'point', variants: ['points'], definition: 'One thirty-second of the compass, 11¼ degrees. Six points is 67½ degrees.', source: `${LEVER}, p.75` },
    { term: 'leeway', variants: ['lee-way'], definition: 'The sideways drift of a ship to leeward of the course she steers; about a point when close-hauled in good conditions.', quote: 'All vessels, however, are supposed to make nearly a point of lee-way, when close-hauled', source: `${FALC}, CLOSE-HAULED` },
    { term: 'griping', variants: ['gripe'], definition: 'A ship’s tendency to come up into the wind, so that she has to carry weather helm.', quote: 'The inclination of a ship to run to windward of her proper course', source: `${STEEL}, sea terms` },
    { term: 'weather helm', variants: [], definition: 'Helm that has to be carried to windward to keep a griping ship on her course.', source: `${LEVER}, p.74` },
    { term: 'steerage-way', variants: ['steerage way'], definition: 'Enough speed through the water for the rudder to act.', quote: 'Such degree of progressive motion of a ship, as will give effect to the motions of the helm', source: `${STEEL}, sea terms` },
    { term: 'headway', variants: ['head-way', 'sternway', 'stern-way'], definition: 'Motion ahead through the water. Sternway is motion astern, and it reverses the effect of the rudder.', quote: 'in going a-stern, if the helm be put a-starboard, it will turn the ship’s head to starboard', source: `${LEVER}, p.71` },
    { term: 'fall off', variants: ['falling off', 'pay off'], definition: 'Of the ship’s head: to turn away from the wind.', source: `${LEVER}, pp.76–79` },
    { term: 'come to', variants: ['coming to'], definition: 'Of the ship’s head: to turn towards the wind.', source: `${LEVER}, pp.76–79` },
    { term: 'luff', variants: [], definition: 'To steer closer to the wind. As an order, to put the helm a-lee.', quote: 'The order to the steersman to put the helm towards the lee side of the ship, in order to sail nearer to the wind', source: `${STEEL}, sea terms` },
    { term: 'bear up', variants: ['bear away'], definition: 'To turn the ship away from the wind by putting the helm up.', quote: 'The act of changing a ship’s course, to make her sail more before the wind', source: `${STEEL}, sea terms` },
    { term: 'weather', variants: ['windward', 'a-weather'], definition: 'The side or direction the wind comes from. The weather brace, weather clew and weather leech are the ones on that side.', source: `${STEEL}, sea terms` },
    { term: 'lee', variants: ['leeward', 'a-lee'], definition: 'The side or direction away from the wind.', source: `${STEEL}, sea terms` },
    { term: 'larboard', variants: ['port'], definition: 'The left side of the ship looking forward. The period word for the side; “port” was already used for helm orders and in a few phrases.', quote: 'PORT. A name given on some occasions to the larboard side of the ship, as, the ship heels to port, top the yards to port', source: `${STEEL}, sea terms`, spellings: 'Steel 1794: larboard for the side, “port the helm” for the order.' },
    { term: 'starboard', variants: [], definition: 'The right side of the ship looking forward.', source: `${STEEL}, sea terms` },
    { term: 'head yards', variants: ['head-yards', 'after yards'], definition: 'The yards of the foremast. The after yards are those of the main and mizen masts. In tacking the after yards are swung first and the head yards second.', source: `${LEVER}, pp.76–77` },
    { term: 'helm', variants: [], definition: 'The tiller; and so the steering gear as a whole. Helm orders name the side the tiller goes to: “starboard the helm” moves the tiller to starboard, the rudder to port and the ship’s head to port.', quote: 'The tiller or helm, which puts the rudder over to port or to the left, goes itself over to starboard, or to the right; therefore, in this position the helm is said to be a-starboard', source: `${LEVER}, p.71` },
    { term: 'tiller', variants: [], definition: 'The bar fixed in the head of the rudder by which it is turned. In a two-decker it lies under the upper-deck beams right aft.', quote: 'a long bar of timber… fixed horizontally in its upper end within the vessel', source: `${FALC}, HELM` },
    { term: 'tiller rope', variants: ['wheel rope', 'tiller-rope'], definition: 'The rope from the fore end of the tiller out to each side and up to the barrel of the wheel.', quote: 'usually composed of untarred rope-yarns, for the purpose of traversing more readily through the blocks', source: `${FALC}, HELM` },
    { term: 'wheel', variants: [], definition: 'The steering wheel on the quarterdeck, with the tiller rope wound round its barrel.', quote: 'Five turns of the tiller-rope are usually wound about the barrel of the wheel', source: `${FALC}, HELM` },
    { term: 'sweep', variants: ['sweep of the tiller'], definition: 'The curved frame under the beams on which the fore end of the tiller travels.', quote: 'A semi-circular frame on which the tiller traverses in large ships; it is fixed under the beams near the fore-end of the tiller, which it supports', source: 'Smyth 1867, SWEEP OF THE TILLER' },
    { term: 'relieving tackles', variants: ['relieving-tackles'], definition: 'Tackles hooked to the tiller to steer by if the wheel or tiller ropes are damaged, or to share the load in heavy weather.', quote: 'used when the tiller-ropes are damaged, have one end made fast to a rope strap, with a thimble on each side of the tiller, and the other end to an eye-bolt in the side', source: `${STEEL}, necessary ropes` },
    { term: 'twiddling lines', variants: [], later: true, definition: 'Lines to secure the wheel when the ship loses way. From Boyd (Royal Navy, 1860).', source: 'Boyd 1860, p.338' },
    { term: 'conn', variants: ['cunning', 'conning', 'con'], definition: 'To direct the helmsman.', quote: 'CUNNING. The art of directing the steersman', source: `${STEEL}, sea terms` },
    { term: 'a-lee', variants: ['helm’s a-lee', 'hard a-lee', 'helm a-lee', 'down helm'], definition: 'Of the helm: put over to the lee side, which turns the ship’s head towards the wind. “The helm’s a-lee!” is also the announcement that begins a tack.', quote: 'A direction to put the helm over to the lee side', source: `${STEEL}, sea terms; ${LEVER}, p.77` },
    { term: 'a-weather', variants: ['helm a-weather', 'hard a-weather', 'up helm', 'hard up'], definition: 'Of the helm: put over to the weather side, which turns the ship’s head away from the wind. “Up helm!” as an order is found in the later manuals.', quote: 'An order to put the helm over to the windward side', source: `${STEEL}, sea terms; ${FALC}, HARD-A-WEATHER` },
    { term: 'steady', variants: ['steddy'], definition: 'Helm order: keep her heading as she goes.', quote: 'to keep the ship in the direction she is going at that instant', source: `${STEEL}, sea terms; ${FALC}, STEERING`, spellings: 'Falconer: steddy.' },
    { term: 'thus', variants: ['very well thus'], definition: 'Helm order when close-hauled: keep her as she is.', quote: 'to keep the ship in her present situation, when sailing with a scant wind', source: `${STEEL}, sea terms` },
    { term: 'no near', variants: ['no nearer', 'near'], definition: 'Helm order: do not steer so close to the wind.', quote: 'An order to the steersman not to keep the ship so close to the wind', source: `${STEEL}, sea terms; ${FALC}, NO NEARER` },
    { term: 'fall not off', variants: [], definition: 'Helm order: keep her up near the wind. The later American equivalent is “nothing off”.', quote: 'to keep the ship near the wind', source: `${STEEL}, sea terms` },
    { term: 'nothing off', variants: [], later: true, definition: 'Helm order: let her come no further from the wind. Found only in Luce (US Navy, 1866); Steel’s equivalent is “Fall not off!”', source: 'Luce 1866' },
    { term: 'meet her', variants: [], definition: 'To put on opposite helm to check a swing before she passes her course. As a formal order it is in the later manuals; as seamen’s language it is in Hutchinson (1777).', quote: 'before he offers to stop or meet her with it', source: 'Hutchinson 1777; Luce 1866' },
    { term: 'right the helm', variants: [], definition: 'To bring the helm amidships.', quote: 'to bring it into midships', source: `${STEEL}, sea terms` },
    { term: 'shift the helm', variants: [], definition: 'To put the helm over to the other side, as when a ship in stays gathers sternway.', quote: 'To alter its position from right to left, or from left to right', source: `${STEEL}, sea terms` },
    { term: 'ready about', variants: ['about ship'], definition: 'The warning order to go to stations for tacking.', quote: 'READY ABOUT! A command of the boatswain to the crew, and implies that all the hands are to be attentive, and at their stations for tacking', source: `${STEEL}, sea terms; ${LEVER}` },
    { term: 'raise tacks and sheets', variants: ['off tacks and sheets', 'up tacks and sheets', 'rise tacks and sheets'], definition: 'The order in tacking to let go the tack and sheet of the mainsail (and in some accounts the foresail) so that the yards can be swung.', source: `${LEVER}, p.77; ${FALC}; Moore 1801`, spellings: 'Falconer: “Up tacks and sheets!” Hutchinson and Lever: “Off tacks and sheets!” Gower, Steel, Moore: “raise tacks and sheets”. “Rise tacks and sheets” is in the US Navy books of the 1860s.' },
    { term: 'mainsail haul', variants: ['main-sail haul', 'haul main-sail, haul'], definition: 'The order in tacking to swing the after yards (main and mizen) round to the new tack.', source: `${LEVER}, p.77; ${FALC}`, spellings: 'Falconer and Moore: “Haul main-sail, haul!” Lever and the seamanship writers: “Main-sail haul!”' },
    { term: 'let go and haul', variants: ['haul of all', 'of all haul'], definition: 'The order in tacking to swing the head yards round to the new tack. “Haul of all” is an alternative for the same order in Falconer, Hutchinson and Moore; in later American books it means swinging every yard at once.', source: `${LEVER}, p.77; ${FALC}; Moore 1801` },
    { term: 'fighting sails', variants: [], later: true, definition: 'The sail a ship is reduced to going into action. The only definition found is Smyth’s of 1867, and it includes the courses.', quote: 'Those to which a ship is reduced when going into action; formerly implying the courses and topsails only', source: 'Smyth 1867, FIGHTING-SAILS' },

    { term: 'becalmed', variants: ['becalm'], definition: 'Of a sail: in the wind-shadow of another and so not drawing. In tacking the after sails are becalmed by the head sails, which is the moment to swing them.', quote: 'the after sails being becalmed by the head ones', source: `${LEVER}, p.77` },
    { term: 'by the stern', variants: ['by the head'], definition: 'Trimmed deeper aft than forward; by the head is the opposite.', quote: 'if a ship be much by the stern, she cannot keep her wind well (because her head will fly off)… and if she be by the head, she cannot easily ware', source: `${LEVER}, p.74` },
    { term: 'lee shore', variants: [], definition: 'A shore to leeward of the ship, on to which the wind is driving her.', source: `${LEVER}, p.95` },
    { term: 'let fall', variants: [], definition: 'The order to drop a loosed sail from the yard so that it hangs in its gear. As a spoken order it is found from 1836 (Glascock) on.', source: 'Glascock 1836; Nares 1862; Totten 1862' },
    { term: 'lie out', variants: ['lay out', 'lay aloft', 'away aloft'], definition: 'Orders for men to go aloft and out along a yard. The wording found is later than the period: “lie-out” (Glascock, Royal Navy, 1836), “Away aloft” and “Lay out” (Nares, Royal Navy, 1862), “Lay aloft” (US Navy). No period Royal Navy wording was found.', source: 'Glascock 1836; Nares 1862; Totten 1862' },

    // ---- The ship's company -------------------------------------------------
    { term: 'forecastle men', variants: ['forecastle-men', 'sheet-anchor men'], definition: 'Older prime seamen stationed forward: anchors, bowsprit, head sails and the fore yard.', quote: 'prime seamen', source: 'Masefield 1905; Smyth 1867, FORECASTLE-MEN (both later)' },
    { term: 'topmen', variants: ['topman'], definition: 'The young, active seamen who work aloft, in three bodies for the fore, main and mizen tops.', source: 'Masefield 1905 (later)' },
    { term: 'afterguard', variants: ['after-guard'], definition: 'The body of less skilled men stationed on the quarterdeck and poop to work the after braces, the mainsail and the driver.', quote: 'stationed on the quarter-deck and poop, to work the after-sails… constituting with waisters the largest part of the crew', source: 'Smyth 1867, AFTER-GUARD; Masefield 1905 (both later)' },
    { term: 'waisters', variants: ['waister'], definition: 'Landsmen and the least skilled men, stationed in the waist to haul on the fore and main sheets and the braces.', quote: 'in former times stationed in the waist in working the ship, as they had little else of duty but hoisting and swabbing the decks', source: 'Smyth 1867, WAISTERS; Masefield 1905 (both later)' },
    { term: 'idlers', variants: ['idler'], definition: 'Day-men such as cooks, tailors and holders, who stand no watch but turn out when all hands are called.', source: 'Masefield 1905 (later)' },
    { term: 'quartermaster', variants: ['quarter-master', 'timoneer'], definition: 'A petty officer who supervises the steering. The men at the wheel, the most expert sailors in turn, are Falconer’s “timoneers”.', source: `${FALC}, STEERING` },
    { term: 'watch', variants: ['larboard watch', 'starboard watch'], definition: 'One of the two halves of the ship’s company, larboard and starboard, which take the deck in turn.', source: 'Masefield 1905 (later)' },
    { term: 'station bill', variants: ['watch bill'], definition: 'The list of where each man goes for each evolution, built from the watch bill so that one watch alone can work the ship. No station bill with numbers for a 74 of this period was found.', source: 'Brady 1848; Boyd 1860; Luce 1866 (all later)' },

    { term: 'marines', variants: [], definition: 'The soldiers of the ship’s company. In working ship they haul on the quarterdeck with the afterguard, and man the capstan bars. Somewhat over 100 in a 74 (general knowledge, not verified).', source: 'Masefield 1905 (later)' },
    { term: 'sail-trimmers', variants: ['sail trimmers'], later: true, definition: 'Men told off at quarters to leave the guns and work the sails in action. The term as found is from US Navy manuals of 1848 and 1866.', source: 'Brady 1848; Luce 1866' },
    { term: 'third rate', variants: ['74', 'seventy-four'], definition: 'A ship of the line of 64 to 80 guns on two decks. The 74 is the standard ship of the line of the period and the reference ship of this tutorial.', quote: 'The complement in a 74 is 650, and in a 64, 500 men', source: `${FALC}, RATES` },

    // ---- Anchors -------------------------------------------------------------
    { term: 'capstan', variants: ['capstern'], definition: 'The upright barrel turned by men at bars, for heaving in the cable and other very heavy pulls. A 74 has a main capstan and a fore (jeer) capstan.', source: `${STEEL}, pp.306–307`, spellings: 'Steel and Lever: capstern.' },
    { term: 'messenger', variants: ['viol'], definition: 'An endless rope round the capstan to which the cable is nipped as it comes in; the cable itself never goes to the capstan. In large ships a viol, led through a block at the mainmast, does the same job.', quote: 'a cablet of sufficient length to go round the capstern, and to pass slack round the rollers forward', source: `${LEVER}, p.109; ${STEEL}, pp.306–307` },
    { term: 'nippers', variants: ['nipper'], definition: 'Short lengths of rope that bind the cable to the messenger, put on forward and taken off as they reach the hatchway.', source: `${LEVER}, p.109` },
    { term: 'cat and fish', variants: ['catted', 'fished'], definition: 'To hoist the anchor’s ring up to the cathead (cat), and then swing its flukes up to the side (fish).', quote: 'The anchor is then catted, and afterwards fished', source: `${STEEL}, p.307` },
  ];

  // ---- Looking a term up ------------------------------------------------------
  const plain = (s) => s.toLowerCase().replace(/[’']/g, '');
  const idOf = (term) => plain(term).replace(/\s+/g, '-');
  const key = (s) => plain(s).replace(/[^a-z0-9]/g, '');

  R.glossaryId = idOf;
  // The entry for a term or any of its variants, however it is hyphenated.
  R.glossaryFind = function (word) {
    const k = key(decodeURIComponent(word));
    return R.GLOSSARY.find((e) => key(e.term) === k) || R.GLOSSARY.find((e) => e.variants.some((v) => key(v) === k)) || null;
  };

  // ---- The page ---------------------------------------------------------------
  const root = document.getElementById('glossary');
  if (!root) return;

  const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;');
  const entries = R.GLOSSARY.slice().sort((a, b) => key(a.term).localeCompare(key(b.term)));
  const letterOf = (e) => key(e.term)[0].toUpperCase();
  const filter = document.getElementById('filter');
  const letters = document.getElementById('letters');
  const count = document.getElementById('count');
  const laterOnly = document.getElementById('later-only');

  function entryHtml(e) {
    const see = (e.see || []).map((t) => `<a href="#${idOf(t)}">${esc(t)}</a>`).join(', ');
    return `<div class="entry${e.later ? ' later' : ''}" id="${idOf(e.term)}" data-letter="${letterOf(e)}">` +
      `<dt><a href="#${idOf(e.term)}">${esc(e.term)}</a>${e.later ? ' <span class="when">later than the period</span>' : ''}` +
      (e.variants.length ? `<span class="variants">${e.variants.map(esc).join(', ')}</span>` : '') + '</dt>' +
      `<dd><p>${esc(e.definition)}</p>` +
      (e.quote ? `<blockquote>“${esc(e.quote)}”</blockquote>` : '') +
      (e.spellings ? `<p class="spell"><b>Spellings.</b> ${esc(e.spellings)}</p>` : '') +
      `<p class="refs">${esc(e.source)}${see ? ` · See ${see}` : ''}</p></dd></div>`;
  }

  let html = '', last = '';
  for (const e of entries) {
    const l = letterOf(e);
    if (l !== last) {
      html += `${last ? '</dl></section>' : ''}<section class="letter" data-letter="${l}"><h2 id="letter-${l}">${l}</h2><dl>`;
      last = l;
    }
    html += entryHtml(e);
  }
  root.innerHTML = html + '</dl></section>';
  letters.innerHTML = [...new Set(entries.map(letterOf))].map((l) => `<a href="#letter-${l}">${l}</a>`).join('');

  function apply() {
    const q = key(filter.value), raw = filter.value.trim().toLowerCase();
    let shown = 0;
    for (const e of entries) {
      const el = document.getElementById(idOf(e.term));
      const text = [e.term, ...e.variants].map(key);
      const hit = (!q || text.some((t) => t.includes(q)) || (raw.length > 2 && e.definition.toLowerCase().includes(raw))) && (!laterOnly.checked || e.later);
      el.hidden = !hit;
      if (hit) shown++;
    }
    for (const sec of root.querySelectorAll('.letter')) sec.hidden = !sec.querySelector('.entry:not([hidden])');
    count.textContent = shown === entries.length ? `${entries.length} terms` : `${shown} of ${entries.length} terms`;
  }
  filter.addEventListener('input', apply);
  laterOnly.addEventListener('change', apply);

  // A link to glossary.html#term, or to any variant spelling, opens that entry.
  function goToHash() {
    const h = location.hash.slice(1);
    if (!h || h.startsWith('letter-')) return;
    const e = document.getElementById(decodeURIComponent(h)) ? null : R.glossaryFind(h);
    const el = document.getElementById(e ? idOf(e.term) : decodeURIComponent(h));
    if (!el) return;
    if (el.hidden) {
      filter.value = '';
      laterOnly.checked = false;
      apply();
    }
    for (const x of root.querySelectorAll('.entry.target')) x.classList.remove('target');
    el.classList.add('target');
    el.scrollIntoView({ block: 'start' });
  }
  window.addEventListener('hashchange', goToHash);
  apply();
  goToHash();
})();
